 const S = {page:sessionStorage.getItem('catherina-page')||'overview', key:'', info:null, state:null, global:null, menuDefaults:null, service:null, globalDirty:false, dirty:false, query:'', tab:'commands', menuTab:'features', menuFeature:'', busy:false, generation:0, contactPicker:'', contactItems:[], contactSearch:'', contactSelection:{}, contactCache:{}, contactLoading:false, contactError:'', contactRequest:0, debugDrafts:{mengka:{action:'get_bot_info',params:'{}'},http:{method:'GET',url:'',headers:'{}',body:''}}, debugResults:{}, debugBusy:false};
 const titles = {overview:['总览','常用功能与当前账号状态'], features:['功能与指令','开关即时保存。'], menus:['共用菜单','菜单正文、前后缀和功能回复由所有 QQ 共用。'], library:['问答与白名单','问答和群发目标只对当前账号生效。'], jobs:['自动任务','保存后会按计划执行，重启后继续。'], access:['全局设置','额外管理 QQ 对所有账号生效；登录账号本人可直接管理。'], settings:['账号设置','自动回复、通知和群级开关，只修改当前 QQ。'], service:['连接与更新','连接萌卡并管理在线更新。'], debug:['接口调试','调用萌卡接口或发送 HTTP 请求，查看完整响应。'], monitor:['监控记录','当前账号命中的监控记录，仅保留最近 7 天。']};
 if(!titles[S.page])S.page='overview';
 const tokens = ['发送者QQ','框架QQ','群号','插件名字','插件版本','现行时间','10位时间戳','13位时间戳','换行符','空格'];
 let toastTimer, serial=Promise.resolve();
 let API_BASE = location.pathname.slice(0, location.pathname.lastIndexOf('/') + 1);
 const apiUrl = path => API_BASE + String(path).replace(/^\//, '');
 async function resolveApiBase(){if(API_BASE==='/')return;try{const probe=await fetch(apiUrl('/api/status'),{headers:{'X-Catherina-UI':'1'}});if(probe.status===404)API_BASE='/';}catch{}}
 function toast(message,error=false) {const node=$('#toast');node.textContent=message;node.className='toast'+(error?' error':'');node.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.hidden=true,error?6500:3000);}
 async function api(path,options={}) {
  let response;try{response=await fetch(apiUrl(path),{...options,headers:{'Content-Type':'application/json','X-Catherina-UI':'1','X-Catherina-Account':S.key,...options.headers},signal:options.signal||AbortSignal.timeout(options.timeout||30000)});}catch(error){if(error.name==='TimeoutError'||error.name==='AbortError')throw new Error('等待响应超时，请先核对执行结果，再决定是否重试。');throw new Error('连接插件后台失败，请检查萌卡连接后重试。');}
  let data;try{data=await response.json();}catch{throw new Error('服务返回了无法读取的响应');}
  if(response.status===401&&!path.startsWith('/api/auth/')){if(S.info?.managed)toast('插件后台会话已结束，请从萌卡插件卡片重新打开',true);else showLogin(false);}
  if(response.status===409&&['/api/config','/api/jobs','/api/global'].includes(path)&&options.method&&options.method!=='GET'){
   if(path==='/api/global')S.global=await api('/api/global');else S.state=await api('/api/config');
   throw new Error('配置刚被其他操作更新，已读取最新版本。你的输入还在，请再保存一次。');
  }
  if(!response.ok)throw new Error(data.error||`请求失败 (${response.status})`);return data;
 }
 function post(path,body={},options={}) {return api(path,{method:'POST',body:JSON.stringify(body),...options});}
 function config(){return S.state?.config;}
 function toggle(id,on,attributes='') {return `<label class="toggle"><input type="checkbox" aria-label="${esc(id)}" ${on?'checked':''} ${attributes}><span></span></label>`;}
 function panel(title,body,actions='') {return `<section class="panel"><header class="panel-heading"><h2>${esc(title)}</h2>${actions}</header>${body}</section>`;}
 function table(headers,rows) {return `<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;}
 function empty(title,body) {return `<div class="empty"><strong>${esc(title)}</strong>${esc(body)}</div>`;}
 function field(key,label,value,type='text',hint='') {let input;if(type==='textarea')input=`<textarea data-field="${esc(key)}" rows="6">${esc(value)}</textarea>`;else if(type==='checkbox')input=toggle(label,!!value,`data-field="${esc(key)}"`);else input=`<input data-field="${esc(key)}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" step="1"':''}>`;return `<div class="form-row"><div><h3>${esc(label)}</h3>${hint?`<p>${esc(hint)}</p>`:''}</div><div>${input}</div></div>`;}
 function tokenButtons(target) {return `<div class="tokens">${tokens.map(t=>`<button type="button" data-token="${esc(t)}" data-target="${esc(target)}">${esc(t)}</button>`).join('')}</div>`;}
 function setDirty(on=true) {S.dirty=on;$('#save').hidden=!on&&!S.globalDirty;$('#status').textContent=(on||S.globalDirty)?'有未保存的修改':'已读取';}
 function readFields(root=$('#content')) {const out={};$$('[data-field]',root).forEach(n=>{let v=n.type==='checkbox'?n.checked:n.value;if(n.type==='number'){v=Number(v);if(!Number.isSafeInteger(v)||v<0)throw new Error('数字格式不正确');}if(n.dataset.array==='numbers')v=String(v).split(/[,，\s]+/).filter(Boolean).map(x=>{const n=Number(x);if(!Number.isSafeInteger(n)||n<=0)throw new Error('QQ 或群号格式不正确');return n;});if(n.dataset.array==='lines')v=String(v).split('\n').map(x=>x.trim()).filter(Boolean);if(n.dataset.field==='menu_content'&&n.dataset.automatic==='true'&&v===S.menuDefaults?.account)v='';out[n.dataset.field]=v;});return out;}
 function save(patch,renderAfter=true) {const key=S.key;const run=async()=>{if(key!==S.key)throw new Error('账号已切换，请重新操作');S.busy=true;try{const state=await api('/api/config',{method:'PATCH',body:JSON.stringify({revision:S.state.revision,patch:typeof patch==='function'?patch(config()):patch})});if(key===S.key){S.state=state;if(renderAfter){setDirty(false);render();}}toast('已保存');return state;}finally{S.busy=false;}};const task=serial.then(run);serial=task.catch(()=>{});return task;}
 function dialog(title,fields,values={},okText='保存',onSave=null) {return new Promise(resolve=>{
  const modal=$('#dialog');if(modal.open){resolve(null);return;}
  $('#dialog-title').textContent=title;$('#dialog-ok').textContent=okText;$('#dialog-error').hidden=true;
  $('#dialog-fields').innerHTML=fields.map(f=>{let input;const required=f.required?'required':'';
   if(f.type==='image')input=`<img class="framework-captcha" src="${esc(values[f.key])}" alt="萌卡图形验证码">`;
   else if(f.type==='textarea')input=`<textarea name="${esc(f.key)}" rows="${f.rows||6}" placeholder="${esc(f.placeholder||'')}" ${required}>${esc(values[f.key])}</textarea>`;
   else if(f.type==='select')input=`<select name="${esc(f.key)}">${f.options.map(o=>`<option value="${esc(o.value)}" ${values[f.key]===o.value?'selected':''}>${esc(o.label)}</option>`).join('')}</select>`;
   else if(f.type==='checkbox')input=`<input type="checkbox" name="${esc(f.key)}" ${values[f.key]?'checked':''}>`;
   else input=`<input name="${esc(f.key)}" type="${esc(f.type||'text')}" value="${esc(values[f.key])}" placeholder="${esc(f.placeholder||'')}" ${required} ${f.min!==undefined?`min="${f.min}"`:''}>`;
   return `<label class="field"><span>${esc(f.label)}</span>${input}${f.hint?`<small>${esc(f.hint)}</small>`:''}</label>`;
  }).join('');
  let answer=null,pending=false;const form=$('#dialog-form');
  const updateFields=()=>{for(const f of fields){if(!f.when&&!f.whenNot)continue;const input=form.elements.namedItem(f.key);let show=f.when?form.elements.namedItem(f.when.key)?.value===f.when.value:true;if(f.whenNot&&form.elements.namedItem(f.whenNot.key)?.value===f.whenNot.value)show=false;input.closest('label').hidden=!show;input.disabled=!show;}};
  const lock=on=>{pending=on;$('#dialog-fields').inert=on;$('#dialog-close').disabled=on;$('#dialog-cancel').disabled=on;$('#dialog-ok').disabled=on;$('#dialog-ok').textContent=on?'正在保存…':okText;};
  const submit=async event=>{event.preventDefault();if(pending||!form.reportValidity())return;const value={};for(const f of fields){if(f.type==='image')continue;const n=form.elements.namedItem(f.key);if(!n.disabled)value[f.key]=f.type==='checkbox'?n.checked:n.value;}
   lock(true);$('#dialog-error').hidden=true;
   try{if(onSave)await onSave(value);answer=value;modal.close();}
   catch(error){$('#dialog-error').textContent=error.message;$('#dialog-error').hidden=false;}
   finally{lock(false);}
  };
  const close=()=>{if(!pending)modal.close();},cancel=event=>{if(pending)event.preventDefault();};
  form.addEventListener('change',updateFields);updateFields();form.addEventListener('submit',submit);modal.addEventListener('cancel',cancel);$('#dialog-close').addEventListener('click',close);$('#dialog-cancel').addEventListener('click',close);
  modal.addEventListener('close',()=>{$$('input[type=password]',modal).forEach(n=>n.value='');form.removeEventListener('change',updateFields);form.removeEventListener('submit',submit);modal.removeEventListener('cancel',cancel);$('#dialog-close').removeEventListener('click',close);$('#dialog-cancel').removeEventListener('click',close);resolve(answer);},{once:true});
  lock(false);modal.showModal();$('input,textarea,select',modal)?.focus();
 });}
 async function confirm(message) {const answer=await dialog(message,[],{},'确认');return answer!==null;}
 function setGlobalDirty(on=true){S.globalDirty=on;setDirty(S.dirty);}
 function contactDirty(){const key=S.contactPicker==='friends'?'mass_friends':'mass',current=config()?.[key]||{};return Object.entries(S.contactSelection).some(([id,on])=>!!current[id]!==on);}
 async function leave() {return (!S.dirty&&!S.globalDirty&&!contactDirty())||await confirm(contactDirty()?'发送名单还有未保存的选择，放弃这些选择？':'还有未保存的修改，丢弃这些修改？');}
 async function getStatus() {S.info=await api('/api/status');$('#version').textContent=S.info.version;$('#logout').hidden=!!S.info.managed||!!S.info.preview;$('#preview-banner').hidden=!S.info.preview;$('#connection').textContent=S.info.preview?'本地界面预览':S.info.active?'萌卡已连接':'萌卡未连接';$('#connection').classList.toggle('online',S.info.active);const accounts=S.info.accounts||[];if(!accounts.some(a=>accountKey(a)===S.key)){S.key=accounts.length?accountKey(accounts[0]):'';S.state=null;}const selected=accounts.find(a=>accountKey(a)===S.key);$('#current-account-number').textContent=selected?String(selected.self_id):'尚未选择 QQ';$('#current-account-state').textContent=S.info.preview?'示例账号':selected?(selected.status===1?'在线':'离线'):'等待账号';$('#current-account-state').classList.toggle('online',selected?.status===1);$('#current-account-client').textContent=selected?(selected.client_type==='linuxqq'?'Linux QQ':'Android QQ'):'';$('#account').innerHTML=accounts.length?accounts.map(a=>`<option value="${esc(accountKey(a))}" ${S.key===accountKey(a)?'selected':''}>${accountLabel(a,accounts)}</option>`).join(''):'<option value="">尚未读取到 QQ 账号</option>';}
 async function load() {const generation=++S.generation;$('#status').textContent='正在读取';await getStatus();S.global=await api('/api/global');S.menuDefaults=await api('/api/menus/defaults');if(S.key){const state=await api('/api/config');if(generation!==S.generation)return;S.state=state;}S.service=await api('/api/service');renderPolicy();if(generation!==S.generation)return;S.globalDirty=false;setDirty(false);render();}
 async function go(page){if(S.busy){toast('正在保存，请稍等');return;}if(!await leave())return;if(page==='menus')S.menuDefaults=await api('/api/menus/defaults');S.contactPicker='';S.contactSelection={};S.contactRequest++;S.page=page;sessionStorage.setItem('catherina-page',page);S.query='';S.globalDirty=false;setDirty(false);render();$('main').scrollTop=0;}
 function render(){if(!S.info)return;renderPolicy();const [title,note]=titles[S.page];$('#page-title').textContent=title;$('#page-note').textContent=note;$('#page-kicker').textContent=S.key?`Catherina / ${S.key}`:'Catherina / Mengka NT';$$('#nav button').forEach(n=>{if(n.dataset.page===S.page)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');});$('#save').hidden=true;$('#mobile-page').innerHTML=Object.entries(titles).map(([key,[label]])=>`<option value="${key}" ${S.page===key?'selected':''}>${esc(label)}</option>`).join('');const content=$('#content');if(!config()&&!['overview','access','service','debug','monitor','menus'].includes(S.page)){content.innerHTML=empty('先连接萌卡并选择 QQ','在“连接与更新”里填写 WebSocket 地址和服务令牌。');return;}const renderers={overview,access,features,menus,library,jobs,settings,service,debug,monitor};content.innerHTML=renderers[S.page]();if(S.page==='monitor'){loadMonitor();}$('#status').textContent=S.key?`当前账号 ${S.key}`:'尚未选择 QQ';}
 function overview(){const c=config(),total=S.info.features.length,on=c?S.info.commands.filter(x=>c.command_switch[x.word]!==false).length:0;const metrics=`<div class="metric-row"><div class="metric"><span>本人可用指令</span><strong>${c?`${on} / ${S.info.commands.length}`:'—'}</strong></div><div class="metric"><span>自定义菜单</span><strong>${(S.global?.config?.menus||[]).length}</strong></div><div class="metric"><span>账号本人触发</span><strong>${c?'默认允许':'选择 QQ 后可用'}</strong></div></div>`;return announcements()+metrics+selfAccessNotice()+`<div class="grid-2">`+panel('开始使用',`<div class="panel-body"><p>用当前登录 QQ 给自己发送“菜单”或“总菜单”。需要调整功能、回复和任务时，在这里选择对应账号。</p><div class="actions"><button data-go="features">管理功能</button><button data-go="menus">编辑菜单</button><button data-go="access">全局设置</button></div></div>`)+panel('当前运行',`<div class="panel-body"><div class="info-row"><span>萌卡连接</span><span>${S.info.active?'已连接':'尚未连接'}</span></div><div class="info-row"><span>插件版本</span><span>${esc(S.info.version)}</span></div><div class="info-row"><span>自动更新</span><span>${S.service?.auto_update?'已开启':'已关闭'}</span></div><div class="info-row"><span>额外管理 QQ</span><span>${esc(c?.owner||S.global?.config?.owner||'未设置，本人正常使用')}</span></div><div class="actions"><button data-go="service">连接与更新</button></div></div>`)+`</div>`;}
 // Codex 修改：收紧重复说明，保留操作所需信息。
 function selfAccessNotice(){return `<div class="self-access"><div><strong>本人指令默认可用</strong><p>自己给自己发指令即可，无需加入名单或逐项开启功能。</p></div></div>`;}
 function access(){const g=S.global?.config||{},c=config();return selfAccessNotice()+panel('额外管理 QQ（可选）',`<div class="panel-body"><p class="service-help">需要另一个 QQ 管理所有登录账号时，填写这里。</p><label class="field"><span>额外管理 QQ</span><input data-global="owner" inputmode="numeric" type="number" min="0" value="${esc(g.owner||'')}" ><small>当前设置：${g.owner?esc(g.owner):'未设置'}</small></label><button class="primary" data-global-save>保存全局设置</button></div>`)+((c?.owner)?panel('当前账号的历史授权',`<div class="panel-body"><p>当前 QQ 仍保留旧版单独设置的主人 ${esc(c.owner)}。它会覆盖全局管理 QQ，本人权限不受影响。</p><button data-owner-inherit>改为继承全局管理 QQ</button></div>`):'')+panel('哪些设置会影响所有 QQ',table(['配置','生效范围'],['<tr><td>额外管理 QQ、全部菜单正文和前后缀</td><td>所有登录 QQ 共用</td></tr>','<tr><td>自动功能、触发词、其他人权限、问答和任务</td><td>只影响当前选择的 QQ</td></tr>']))+`<div class="actions"><button data-global-menu-go>编辑全局总菜单</button></div>`;}
 function featureMode(f,c=config()){const rule=c.access?.[f.id];return rule&&rule!=='default'?rule:(c.permits[f.id]||[]).length?'allowlist':f.owner&&f.id!=='custom_menu'?'owner':'everyone';}
 function permissionSummary(f,c=config()){const rule=featureMode(f,c);return rule==='owner'?'不额外开放':rule==='everyone'?'所有人':`指定名单 · ${(c.permits[f.id]||[]).length} 人`;}

 function access(){const g=S.global?.config||{},c=config(),disabled=new Set(g.disabled_accounts||[]),accounts=S.info.accounts||[];return selfAccessNotice()+panel('接入账号',`<div class="panel-body"><p class="service-help">只勾选希望 Catherina 接入的 QQ。取消勾选后，该账号不再处理消息、自动任务或发送操作；原设置会保留，之后可重新启用。</p>${accounts.length?`<div class="account-access-list">${accounts.map(a=>{const key=accountKey(a);const enabled=!disabled.has(key);return `<label class="account-access-row"><span><strong>${esc(accountLabel(a,accounts))}</strong><small>${a.status===1?'在线':'离线'} · ${enabled?'已接入':'未接入'}</small></span>${toggle('接入 '+a.self_id,enabled,`data-account-enabled="${esc(key)}"`)}</label>`;}).join('')}</div><button class="primary" data-account-save>保存接入账号</button>`:empty('尚未读取到账号','刷新 QQ 列表后可以选择接入账号。')}</div>`)+panel('额外管理 QQ（可选）',`<div class="panel-body"><p class="service-help">需要另一个 QQ 管理所有登录账号时，填写这里。</p><label class="field"><span>额外管理 QQ</span><input data-global="owner" inputmode="numeric" type="number" min="0" value="${esc(g.owner||'')}" ><small>当前设置：${g.owner?esc(g.owner):'未设置'}</small></label><button class="primary" data-global-save>保存全局设置</button></div>`)+((c?.owner)?panel('当前账号的历史授权',`<div class="panel-body"><p>当前 QQ 仍保留旧版单独设置的主人 ${esc(c.owner)}。它会覆盖全局管理 QQ，本人权限不受影响。</p><button data-owner-inherit>改为继承全局管理 QQ</button></div>`):'')+panel('哪些设置会影响所有 QQ',table(['配置','生效范围'],['<tr><td>接入账号、额外管理 QQ、全部菜单正文和前后缀</td><td>所有 QQ 共用</td></tr>','<tr><td>自动功能、触发词、其他人权限、问答和任务</td><td>只影响当前已接入的 QQ</td></tr>']))+`<div class="actions"><button data-global-menu-go>编辑全局总菜单</button></div>`;}
 function features(){
  const c=config(),q=S.query.toLowerCase();
  const toolbar=`<div class="toolbar"><div class="tabs"><button data-tab="modules" class="${S.tab==='modules'?'active':''}">自动功能与开关 ${S.info.features.length}</button><button data-tab="commands" class="${S.tab==='commands'?'active':''}">触发指令 ${S.info.commands.length}</button></div><input id="search" class="search" type="search" placeholder="搜索功能或指令 · Ctrl K" aria-label="搜索功能或指令" value="${esc(S.query)}"></div>`;
  if(S.tab==='modules'){
   const items=S.info.features.filter(f=>(f.title+f.description+f.command).toLowerCase().includes(q));
   return selfAccessNotice()+toolbar+`<div class="actions bulk-actions"><button data-bulk="on">全部开启</button><button data-bulk="off">全部关闭</button><span class="small muted">控制自动运行与其他人触发。</span></div><div class="module-grid">${items.map(f=>`<article class="module feature-row"><div class="feature-description"><h2>${esc(f.title)}</h2><p>${esc(f.description)}</p><span class="feature-command">${f.command?'指令：'+esc(c.aliases[f.command]||f.command):'由事件自动触发'}</span></div><div class="feature-access">${f.command?`<span>其他人指令权限</span><strong>${esc(permissionSummary(f,c))}</strong><button data-permit="${esc(f.id)}">管理额外授权</button>`:`<span>触发方式</span><strong>按事件自动运行</strong><button data-go="settings">查看账号设置</button>`}</div><div class="feature-toggle"><span>${c.enabled[f.id]?'已开启':'已关闭'}</span>${toggle(f.title,!!c.enabled[f.id],`data-switch="${esc(f.id)}"`)}</div></article>`).join('')}</div>`+(items.length?'':empty('没有匹配的功能','换一个关键词试试。'));
  }
  const commands=S.info.commands.filter(x=>(x.word+x.usage+(c.aliases[x.word]||'')).toLowerCase().includes(q)).map(x=>{
   const feature=S.info.features.find(f=>f.id===x.feature)||{id:x.feature};let usage=x.usage||x.word;
   const alias=c.aliases[x.word];if(alias&&usage.startsWith(x.word))usage=alias+usage.slice(x.word.length);
   return {...x,displayUsage:usage.split(/[；;]/).map(line=>line.trim()).filter(Boolean).flatMap(line=>friendlyMenuLines(feature,line)).join('\n')};
  });
  return selfAccessNotice()+toolbar+'<div class="actions bulk-actions"><button data-bulk="commands">全部启用指令</button></div>'+panel('触发指令',table(['原始指令','实际触发词','操作示例','启用'],commands.map(x=>`<tr><td>${esc(x.word)}</td><td><input data-alias="${esc(x.word)}" value="${esc(c.aliases[x.word]||x.word)}" aria-label="${esc(x.word)}的触发词"></td><td><div class="command-examples">${esc(x.displayUsage)}</div></td><td>${toggle(x.word,c.command_switch[x.word]!==false,`data-command="${esc(x.word)}"`)}</td></tr>`)));
 }

 function friendlyMenuLines(feature,line){
  const id=feature.id,command=line.trim().split(/\s+/)[0];
  if(id==='timed'&&line==='定时群发（旧指令，请选择群聊或好友）')return ['定时群发群 每天晚上8点发 晚安','定时群发好友 每天晚上8点发 晚安'];
  if(id==='timed'&&line.startsWith('定时群发群 '))return ['定时群发群 每天晚上8点发 晚安'];
  if(id==='timed'&&line.startsWith('定时群发好友 '))return ['定时群发好友 每天晚上8点发 晚安'];
  if(id==='timed'&&line.includes('HH:MM'))return [`${command} 每天晚上8点发 晚安`];
  if(id==='timed'&&line.includes('取消'))return [line.startsWith('取消')?line:`取消${command}`];
  if(id==='timedss'&&line.includes('HH:MM'))return [`${command} 每天晚上8点发 今晚的动态`];
  if(id==='timedss'&&line.includes('取消'))return [line.startsWith('取消')?line:`取消${command}`];
  if(id==='loop'&&line==='循环群发（旧指令，请选择群聊或好友）')return ['循环群发群 10分钟 我马上到','循环群发好友 10分钟 晚安'];
  if(id==='loop'&&line.startsWith('循环群发群 '))return ['循环群发群 每隔10分钟发 我马上到'];
  if(id==='loop'&&line.startsWith('循环群发好友 '))return ['循环群发好友 每隔10分钟发 晚安'];
  if(id==='loop'&&line.includes('间隔秒'))return [`${command} 每隔10分钟发 晚安`];
  if(id==='loop'&&line.includes('停止'))return [line.startsWith('停止')?line:`停止${command}`];
  if(id==='qunfa'&&line==='群发（旧指令，请选择群聊或好友）')return ['群发群 今晚8点集合','群发好友 晚安'];
  if(id==='qunfa'&&line==='群发群 内容')return ['群发群 今晚8点集合'];
  if(id==='qunfa'&&line==='群发好友 内容')return ['群发好友 晚安'];
  if(line==='群发群 添加 群号')return ['群发群 添加 123456'];
  if(line==='群发群 删除 群号')return ['群发群 删除 123456'];
  if(line==='群发好友 添加 QQ号')return ['群发好友 添加 12345678'];
  if(line==='群发好友 删除 QQ号')return ['群发好友 删除 12345678'];
  if(id==='online_notify'&&line.includes('添加/删除 QQ')){const base=line.replace(/\s+添加\/删除 QQ$/,'');return [base+' 添加 12345678',base+' 删除 12345678'];}
  if(line.includes('全体禁言 开/关')||line.includes('上线通知 开/关')){const base=line.replace(/\s+开\/关$/,'');return [base+' 开',base+' 关'];}
  if(line.includes('禁言 QQ 秒数')){const base=line.replace(/\s+QQ 秒数.*$/,'');return [base+' 12345678 60',base+' 12345678 0'];}
  if(line.includes('字符 统计/反转/全角/半角 内容')){const base=line.replace(/\s+统计\/反转\/全角\/半角 内容$/,'');return ['统计','反转','全角','半角'].map(action=>base+' '+action+' 示例文本');}
  if(line.includes('[长度]'))return [line.replace('[长度]','20')];
  if(line.includes('[群号]'))return [line.replace('[群号]','123456')];
  if(line.includes('[QQ]')&&line.includes('[次数]'))return [line.replace('[QQ]','12345678').replace('[次数]','10')];
  if(line.includes('添加群发群 群号')||line.includes('删除群发群 群号'))return [line.replace(' 群号',' 123456')];
  if(line.includes('HH:MM'))return [line.replace('HH:MM','每天晚上8点')];
  if(line==='群发 内容（旧指令，仅发送到群名单）')return ['群发群 今晚8点集合'];
  if(line==='开始群发群 内容')return ['开始群发群 今晚8点集合'];
  if(line.includes(' QQ或群号 内容'))return [line.replace(' 好友/群 QQ或群号 内容',' 群 123456 群消息内容')];
  if(line.includes(' QQ 备注名'))return [line.replace(' QQ 备注名（清空则输入 清空）',' 12345678 好友备注')];
  if(line.includes(' QQ 内容（清空则输入 清空）'))return [line.replace(' QQ 内容（清空则输入 清空）',' 12345678 管理员')];
  if(line.includes(' QQ（全局）'))return [line.replace(' QQ（全局）',' 12345678')];
  if(line.includes(' 表情ID（0 为停用）'))return [line.replace(' 表情ID（0 为停用）',' 6'),line.replace(' 表情ID（0 为停用）',' 0')];
  if(line.includes(' 问题|答案'))return [line.replace(' 问题|答案',' 你好|你好呀')];
  if(line.includes(' 删除 问题'))return [line.replace(' 删除 问题',' 删除 你好')];
  if(line.includes('初始化配置（生成默认全局菜单，不覆盖其他设置）'))return [line.replace('（生成默认全局菜单，不覆盖其他设置）','')];
  if(line.includes(' 功能名称'))return [line.replace(' 功能名称',' 群发')];
  if(line.includes('自定义菜单 添加 触发词|回复'))return [line.replace(' 触发词|回复',' 天气|今晚晴朗')];
  if(line.includes('自定义菜单 删除 触发词'))return [line.replace(' 触发词',' 天气')];
  if(line.includes('关键词'))return [line.replace('关键词','群发')];
  if(line==='反馈 内容')return ['反馈 说明一下遇到的问题'];
  if(line==='上线通知 内容 文本')return ['上线通知 内容 我上线啦'];
  if(line==='公告 内容')return ['公告 今晚8点开始维护'];
  if(line==='设置艾特回复 内容')return ['设置艾特回复 你好呀'];
  if(line==='设置戳一戳回复 内容')return ['设置戳一戳回复 别戳啦'];
  if(line==='个性签名 内容（清空则输入 清空）')return ['个性签名 今天也要开心'];
  if(line==='菜单前缀 内容（清空则输入 清空）')return ['菜单前缀 欢迎使用本菜单'];
  if(line==='菜单后缀 内容（清空则输入 清空）')return ['菜单后缀 祝你今天愉快'];
  if(line==='踢人 QQ')return ['踢人 12345678'];
  if(line==='成员查询 QQ')return ['成员查询 12345678'];
  if(line==='秒赞 添加 评论')return ['秒赞 添加 晚安'];
  if(line==='秒赞 删除 序号')return ['秒赞 删除 1'];
  if(line.includes('歌名'))return [line.replace('歌名','稻香')];
  if(line.includes(' 秒'))return [line];
  return [line.replace(/\[QQ\]/g,'12345678').replace(/\[次数\]/g,'10').replace(/\[群号\]/g,'123456').replace(/\[长度\]/g,'20')];
 }
 function menuGroups(){return S.menuDefaults?.categories||[];}
 function menus(){
  const g=S.global?.config||{},groups=menuGroups(),current=S.menuDefaults?.preview||{};
  const actual=panel('总菜单 · QQ 实际回复',`<div class="panel-body"><pre class="shared-menu-preview">${esc(current.global||g.menu_content||'')}</pre><p class="small muted">${g.menu_automatic?'默认总菜单按分类整理，新版自动同步。':'当前使用你保存的自定义正文。'} 菜单正文和前后缀由所有 QQ 共用。</p></div>`,`<div class="actions"><button data-copy-menu="global">复制菜单</button><button data-shared-menu-edit>编辑正文与前后缀</button><button data-shared-menu-default>恢复默认</button></div>`);
  let content;
  if(S.menuTab==='all')content=`<div class="menu-command-groups">${groups.map(f=>`<section class="menu-command-group"><button class="menu-group-title" data-menu-feature="${esc(f.id)}">${esc(f.trigger)}</button><pre class="shared-menu-preview">${esc(f.reply)}</pre></section>`).join('')}</div>`;
  else if(S.menuFeature){
   const category=groups.find(item=>item.id===S.menuFeature),feature=S.info.features.find(f=>f.id===S.menuFeature),reply=category?.reply||current.features?.[feature?.id]||'',title=category?.trigger||(feature?feature.title+'菜单':'');
   const editable=(category?.features||[feature?.id]).filter(id=>S.info.features.some(f=>f.id===id));
   content=title?`<div class="menu-detail"><button class="menu-back" data-menu-feature="">返回分类目录</button><div class="menu-detail-head"><h3>${esc(title)}</h3><div class="actions"><button data-copy-menu="${esc(S.menuFeature)}">复制回复</button>${editable.length===1?`<button data-builtin-edit="${esc(editable[0])}">编辑菜单正文</button>`:''}</div></div><p class="small muted">发送“${esc(title)}”查看。以下内容跟随当前 QQ 的触发词和指令开关。</p><pre class="shared-menu-preview menu-detail-reply">${esc(reply)}</pre>${editable.length>1?`<details class="menu-settings"><summary>编辑这类功能的菜单正文</summary><div class="actions">${editable.map(id=>{const f=S.info.features.find(item=>item.id===id);return `<button data-builtin-edit="${esc(id)}">${esc(f.title)}菜单</button>`;}).join('')}</div><p class="small muted">这里修改正文后，所有 QQ 共用；默认正文会按各 QQ 的触发词生成。</p></details>`:''}</div>`:empty('没有找到这个菜单','返回分类目录重新选择。');
  }else content=`<div class="menu-feature-list">${groups.map(f=>`<button class="menu-feature-item" data-menu-feature="${esc(f.id)}"><strong>${esc(f.trigger)}</strong><span>查看实际回复</span></button>`).join('')}</div>`;
  const custom=(g.menus||[]).length?table(['触发词','回复内容','会话范围','操作'],g.menus.map((m,i)=>`<tr><td><strong>${esc(m.trigger)}</strong></td><td><div class="preview">${esc(m.reply)}</div></td><td>${m.global?'好友和群':'仅好友'}</td><td><div class="actions"><button data-menu-edit="${i}">编辑</button><button data-menu-delete="${i}">删除</button></div></td></tr>`)):empty('暂未添加其他菜单','添加一次，所有登录 QQ 都能使用。');
  return actual+`<div class="menu-tabs" role="tablist" aria-label="指令菜单"><button role="tab" aria-selected="${S.menuTab==='features'}" class="${S.menuTab==='features'?'active':''}" data-menu-tab="features">分类目录</button><button role="tab" aria-selected="${S.menuTab==='all'}" class="${S.menuTab==='all'?'active':''}" data-menu-tab="all">展开全部回复</button></div>`+panel('分类菜单 · 当前 QQ 的回复',content)+panel('共用自定义菜单',custom,'<button data-menu-add>添加菜单</button>');
 }
 async function saveShared(patch){if(S.busy)throw new Error('正在保存，请稍等');S.busy=true;try{S.global=await api('/api/global',{method:'PATCH',body:JSON.stringify({revision:S.global.revision,patch})});setGlobalDirty(false);let refreshed=true;try{S.menuDefaults=await api('/api/menus/defaults');}catch{refreshed=false;}render();toast(refreshed?'菜单已保存，所有 QQ 共用':'菜单已保存，预览尚未刷新，可点“重新读取”',!refreshed);}finally{S.busy=false;}}
 function builtinMenus(){const c=config();return panel('功能菜单内容',table(['菜单触发词','实际回复内容','操作'],S.info.features.map(f=>{const content=S.global?.config?.replies?.[f.id]||S.menuDefaults?.features?.[f.id]||S.info.commands.filter(x=>x.feature===f.id).map(x=>x.usage).join('\n')||'由事件触发，可在账号设置中配置。';return `<tr><td>${esc(f.title)}</td><td><div class="preview">${esc(content)}</div></td><td><button data-builtin-edit="${esc(f.id)}">编辑内容</button></td></tr>`})));}
 function contacts(kind){return S.contactCache[`${S.key}:${kind}`]||[];}
 function contactChosenCount(){const key=S.contactPicker==='friends'?'mass_friends':'mass';return Object.values({...config()?.[key],...S.contactSelection}).filter(Boolean).length;}
 function updateContactSummary(){const node=$('[data-contact-summary]');if(node)node.textContent=`本次选择 ${contactChosenCount()} 个对象${contactDirty()?' · 尚未保存':' · 已保存'}`;}
 async function loadContacts(kind){const key=S.key,request=++S.contactRequest;S.contactLoading=true;S.contactError='';render();try{const data=await api('/api/contacts?kind='+kind,{timeout:75000});if(key===S.key&&request===S.contactRequest)S.contactCache[`${key}:${kind}`]=data.items||[];}catch(error){if(key===S.key&&request===S.contactRequest)S.contactError=error.message;}finally{if(key===S.key&&request===S.contactRequest){S.contactLoading=false;if(S.page==='library')render();}}}
 function massTargets(title,kind,key){
  const c=config(),items=c[key]||{},entries=Object.entries(items).filter(([,on])=>on),picker=S.contactPicker===kind,list=contacts(kind);
  const rows=entries.map(([id])=>{const contact=list.find(x=>String(x.id)===id);return `<li><div><strong>${esc(contact?.name||contact?.remark||contact?.nickname||'读取联系人后显示名称')}</strong><small>${kind==='groups'?'群号':'QQ 号'} ${esc(id)}</small></div><button class="danger" data-mass-delete="${esc(id)}" data-mass-kind="${kind}">移除</button></li>`});
  const filtered=list.filter(x=>{const q=S.contactSearch.trim().toLowerCase();return !q||[x.id,x.name,x.nickname,x.remark].some(v=>String(v||'').toLowerCase().includes(q));});
  const pickerUI=picker?`<div class="contact-picker"><div class="contact-picker-heading"><strong data-contact-summary>本次选择 ${contactChosenCount()} 个对象${contactDirty()?' · 尚未保存':' · 已保存'}</strong><button data-contact-refresh="${kind}" ${S.contactLoading?'disabled':''}>${S.contactLoading?'正在读取…':'刷新列表'}</button></div><p class="service-help">勾选接收对象，取消勾选可移出名单。搜索不会清除其他选择。</p>${S.contactLoading?'<p class="inline-status" role="status">正在从当前 QQ 读取完整列表，联系人较多时需要稍等…</p>':''}${S.contactError?`<p class="inline-error" role="alert">${esc(S.contactError)}<br>可以刷新重试，或先手动输入号码。</p>`:''}<label class="field"><span>搜索群名、昵称、备注或号码</span><input data-contact-search value="${esc(S.contactSearch)}" placeholder="输入关键词筛选"></label><div class="actions"><button data-contact-select="all">选择搜索结果</button><button data-contact-select="none">取消搜索结果</button><span class="small muted">显示 ${filtered.length} / ${list.length} 个</span></div><div class="contact-results">${filtered.map(x=>{const id=String(x.id),checked=Object.hasOwn(S.contactSelection,id)?S.contactSelection[id]:!!items[id];return `<label class="contact-option ${checked?'is-selected':''}"><input type="checkbox" data-contact-check="${esc(id)}" ${checked?'checked':''}><span><strong>${esc(x.name||x.remark||x.nickname||'未命名')}</strong><small>${kind==='groups'?'群号':'QQ 号'} ${esc(id)}${kind==='friends'&&x.nickname&&x.remark?` · ${esc(x.nickname)}`:''}</small></span></label>`;}).join('')||(!S.contactLoading&&!S.contactError?'<p class="small muted">没有匹配的联系人，可以换个关键词。</p>':'')}</div><div class="contact-save-bar"><button class="primary" data-contact-add ${S.contactLoading?'disabled':''}>保存发送名单</button><span class="small muted">保存后，新群发和自动任务使用这份名单。</span></div></div>`:'';
  return panel(title,`<div class="panel-body"><p class="service-help">只向名单中选中的${kind==='groups'?'群':'好友'}发送。${kind==='friends'?'每位好友通过私聊收到。':'群成员在群聊中收到。'}</p>${entries.length?`<ul class="selected-contacts">${rows.join('')}</ul>`:empty(`还没有选择${kind==='groups'?'群':'好友'}`,'从当前 QQ 的联系人列表选择，或手动输入号码。')}${pickerUI}</div>`,`<div class="actions"><button data-contact-open="${kind}">${picker?'收起选择':'从当前 QQ 选择'}</button><button data-mass-add-kind="${kind}">手动输入号码</button></div>`);
 }
 function library(){const c=config(),qs=Object.entries(c.qa);return panel('问答库',qs.length?table(['问题','回答','操作'],qs.map(([q,a],i)=>`<tr><td>${esc(q)}</td><td><div class="preview">${esc(a)}</div></td><td><div class="actions"><button data-qa-edit="${i}">编辑</button><button class="danger" data-qa-delete="${i}">删除</button></div></td></tr>`)):empty('问答库为空','问题精确命中时自动回复，不会和菜单重复回复。'),'<button data-qa-add>添加问答</button>')+massTargets('接收群消息的群','groups','mass')+massTargets('接收私聊消息的好友','friends','mass_friends');}
 function massCount(target){const c=config();return target==='friend'?(c.enabled.qunfa?Object.values(c.mass_friends||{}).filter(Boolean).length:0):Object.entries(c.mass||{}).filter(([id,on])=>on&&(c.group_switch?.[id]?.qunfa??c.enabled.qunfa)).length;}
 function jobs(){const c=config(),kind={loop:'循环群发',timed:'每天定时群发',timedss:'每天定时说说'},date=stamp=>new Date(stamp*1000).toLocaleString('zh-CN',{month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'});
  const cards=(c.jobs||[]).map((j,i)=>{const blocked=j.enabled&&c.enabled[j.kind]===false,target=j.target||'group',count=target==='both'?`${massCount('group')} 个群、${massCount('friend')} 位好友`:target==='friend'?`${massCount('friend')} 位好友`:`${massCount('group')} 个群`;return `<article class="job-card"><header><div><h2>${kind[j.kind]}</h2><span class="job-state ${blocked?'is-warning':''}">${blocked?'对应功能已关闭':j.enabled?'已启用':'已暂停'}</span></div>${toggle(kind[j.kind],j.enabled,`data-job="${i}"`)}</header><dl class="job-facts"><div><dt>发送给</dt><dd>${j.kind==='timedss'?'QQ 空间':esc(count)}</dd></div><div><dt>${j.kind==='loop'?'间隔':'每天时间'}</dt><dd>${j.kind==='loop'?'每隔 '+durationLabel(j.interval):esc(j.time)}</dd></div><div><dt>下次执行</dt><dd>${j.enabled&&!blocked&&j.next?esc(date(j.next)):'已暂停'}</dd></div></dl><p class="job-message">${esc(j.text)}</p><div class="job-last"><strong>${j.last_run?'最近执行 · '+esc(date(j.last_run)):'尚未执行'}</strong>${j.last_run?`<pre>${esc(j.last_result||'执行结果尚未记录')}</pre>`:'<p>执行后会在这里显示发送结果和失败原因。</p>'}</div><footer class="actions"><button data-job-edit="${i}">编辑任务</button><button class="danger" data-job-delete="${i}">删除任务</button>${blocked?'<button data-go="features">查看功能开关</button>':''}</footer></article>`;}).join('');
  return `<div class="jobs-toolbar"><div><strong>当前可发送：${massCount('group')} 个群 · ${massCount('friend')} 位好友</strong><p>自动任务跟随当前 QQ 的发送名单；保存后重启仍会保留。</p></div><div class="actions"><button data-go="library">管理发送名单</button><button class="primary" data-job-add>添加任务</button></div></div>`+(cards?`<div class="job-grid">${cards}</div>`:empty('还没有自动任务','先选择发送对象，再添加循环群发、定时群发或定时说说。'));
 }
 function settings(){const c=config();const arrayField=(key,label,values,hint)=>field(key,label,(values||[]).join('\n'),'textarea',hint).replace(`data-field="${key}"`,`data-field="${key}" data-array="${key==='notify_targets'||key==='miao_users'?'numbers':'lines'}"`);return selfAccessNotice()+panel('回复与提醒',field('cooldown','被动回复冷却（秒）',c.cooldown,'number','艾特、戳一戳和表情回应按会话限频。')+field('xuhuo_time','续火提醒时间',c.xuhuo_time,'time','按程序所在机器的本地时间执行。')+field('xuhuo_text','续火提醒内容',c.xuhuo_text,'textarea','每天到点发给当天没聊过的好友，支持上下文变量。'))+panel('自动回复',field('at_text','艾特回复内容',c.at_text,'textarea')+field('poke_text','戳一戳回复内容',c.poke_text,'textarea')+field('emoji','表情回应 ID',c.emoji,'text','留空不回应；是否启用由功能开关控制。')+arrayField('phrases','随机回话语料',c.phrases,'每行一条。'))+panel('上线通知',field('notify','自动发送上线通知',c.notify,'checkbox','开关即时保存，以下文字编辑后保存。')+arrayField('notify_targets','通知对象 QQ',c.notify_targets,'每行一个或使用逗号分隔。')+field('notify_text','通知内容',c.notify_text,'textarea','支持菜单页列出的全部上下文变量。'))+panel('秒赞秒评',field('poll_seconds','空间检查间隔（秒）',c.poll_seconds,'number','30–3600 秒，仅处理启用后的新动态。')+arrayField('miao_users','仅处理这些 QQ',c.miao_users,'留空处理所有好友的新动态。')+arrayField('comments','评论语料',c.comments,'每行一条，留空只点赞。'))+groupSettings();}
