 async function editGroup(id){if(!await leave())return;const c=config(),rules=c.group_switch?.[id]||{},fields=[{key:'id',label:'群号',required:true},...S.info.features.map(f=>({key:'g_'+f.id,label:f.title,type:'select',options:[{value:'inherit',label:'继承账号 · '+(c.enabled[f.id]?'开启':'关闭')},{value:'on',label:'这个群单独开启'},{value:'off',label:'这个群单独关闭'}]}))],values={id:id||''};for(const f of S.info.features)values['g_'+f.id]=Object.hasOwn(rules,f.id)?rules[f.id]?'on':'off':'inherit';const result=await dialog(id?'编辑群级开关':'添加群级开关',fields,values);if(!result)return;const ids=parseIDs(result.id);if(ids.length!==1)throw new Error('一次填写一个群号');const next={};for(const f of S.info.features)if(result['g_'+f.id]!=='inherit')next[f.id]=result['g_'+f.id]==='on';const groups=clone(c.group_switch||{});if(id&&String(ids[0])!==id&&Object.hasOwn(groups,String(ids[0])))throw new Error('这个群已有单独配置，请直接编辑原配置');if(id&&String(ids[0])!==id)delete groups[id];if(Object.keys(next).length)groups[String(ids[0])]=next;else delete groups[String(ids[0])];await save({group_switch:groups});}
 function readGlobalFields(){const patch={};$$('[data-global]').forEach(n=>{let value=n.value;if(n.type==='number'){value=Number(value||0);if(!Number.isSafeInteger(value)||value<0)throw new Error('QQ 号码格式不正确');}if(n.dataset.global==='menu_content'&&n.dataset.automatic==='true'&&value===S.menuDefaults?.global)value='';patch[n.dataset.global]=value;});return patch;}

