 const shownAnnouncements=new Set();
 function activeAnnouncements(){const now=Math.floor(Date.now()/1000);return [...(S.service?.policy?.announcements||[])].filter(a=>(!a.start||a.start<=now)&&(!a.end||a.end>now)).sort((a,b)=>Number(b.pinned)-Number(a.pinned));}
 function announcements(){return activeAnnouncements().map(a=>panel(a.title,`<div class="panel-body"><p class="announcement-body">${esc(a.body)}</p></div>`)).join('');}
 function renderPolicy(){
  if(S.info?.preview){$('#policy-banner').hidden=true;return;}
  const p=S.service?.policy;if(!p)return;const banner=$('#policy-banner');
  banner.hidden=!p.blocked&&!p.message;
  banner.textContent=[p.blocked?p.reason:'',p.message].filter(Boolean).join('。');
  const notice=activeAnnouncements().find(a=>{let read=false;try{read=localStorage.getItem('catherina-announcement-'+a.id)==='read';}catch{}return a.important&&!read&&!shownAnnouncements.has(a.id);});
  if(!notice||S.dirty||$('#dialog').open||$('#announcement-dialog').open)return;
  shownAnnouncements.add(notice.id);const dialog=$('#announcement-dialog');
  $('#announcement-title').textContent=notice.title;$('#announcement-body').textContent=notice.body;
  const close=()=>dialog.close();$('#announcement-close').onclick=close;$('#announcement-ok').onclick=close;
  dialog.addEventListener('close',()=>{try{localStorage.setItem('catherina-announcement-'+notice.id,'read');}catch{}},{once:true});
  dialog.showModal();
 }
 function service(){
  const s=S.service||{},u=s.update||{},fu=s.framework_update||{},frameworkLabels={checking:'正在检查萌卡登录与更新版本',downloading:'正在下载并校验新版',uploading:'正在提交给当前萌卡安装',installing:'萌卡已接收，等待插件重启',login_required:'请登录当前萌卡后继续在线更新',approval_required:'新版权限有变化，请确认后安装',current:'当前已是最新版',error:'在线更新未完成'},labels={idle:'等待检查',checking:'正在检查新版',current:'当前已是最新版',ahead:'当前版本高于更新源，等待更新源同步',available:'发现新版本',downloading:'正在下载并校验',installing:'正在安装，即将重启',error:'更新未完成'};
  const connection=s.managed?`<p class="service-help">连接由萌卡框架管理，无需重复填写令牌。</p><dl class="service-facts"><div><dt>连接方式</dt><dd>${s.transport==='native-ipc-v1'?'原生 IPC':'托管 WebSocket'}</dd></div>${s.transport==='websocket-v1'?`<div><dt>WebSocket</dt><dd class="endpoint">${esc(s.url)}</dd></div>`:''}<div><dt>连接状态</dt><dd>${S.info.active?'已连接':'等待连接'}</dd></div></dl><label class="field"><span>萌卡管理接口地址（可选）</span><input data-framework-admin-url value="${esc(s.framework_admin_url||'')}" placeholder="自动读取；不通时填写 http://127.0.0.1:7891"><small>在线更新需要访问萌卡管理接口。留空时读取官方接口返回的地址；只有自动地址不可用时才填写。</small></label><button data-framework-address-save>保存管理地址</button><button data-refresh-accounts>刷新 QQ 列表</button>`:`<p class="service-help">填写萌卡的正向 WebSocket 地址和服务令牌。</p><label class="field"><span>WebSocket 地址</span><input data-service="url" value="${esc(s.url)}" placeholder="ws://127.0.0.1:3001/"></label><label class="field"><span>服务令牌</span><input data-service="token" type="password" autocomplete="off" placeholder="${s.token_set?'已保存，留空保持不变':'填写萌卡服务令牌'}"></label><div class="actions"><button class="primary" data-connection-save>保存并连接</button><button data-refresh-accounts>刷新 QQ 列表</button></div>`;
  return `<div class="service-layout">`+panel('萌卡连接',`<div class="panel-body">${connection}</div>`)+panel('版本与自动更新',`<div class="panel-body"><div class="version-pair"><div><span>正在使用</span><strong>${esc(u.current||S.info.version)}</strong></div><div><span>${u.status==='error'?'上次读取版本':'更新源版本'}</span><strong>${esc(u.latest||'—')}</strong></div></div><p class="update-status update-status-${esc(u.status||'idle')}" role="status">${esc(frameworkLabels[fu.stage]||labels[u.status]||'等待检查')}</p>${(fu.error||u.error)?`<p class="error service-help">${esc(fu.error||u.error)}</p>`:''}<div class="auto-update-row"><div><strong>后台自动更新</strong><p>${s.managed?'每小时检查一次；在线安装需要当前萌卡的管理员登录会话有效。':'每小时检查一次，下载校验后安装并自动重启。'}</p></div>${toggle('后台自动更新',!!s.auto_update,'data-auto-update="1"')}</div><p class="service-help">${s.managed?'点击“立即在线更新”会自动下载、校验，并交给当前萌卡安装；不需要手动保存或上传 ZIP。':'点击“立即在线更新”会自动下载、校验并安装，不需要重新导入。'}</p><p class="service-help">安装前会校验更新清单与安装包；校验失败时保留当前版本，可以稍后重新检查。</p><dl class="service-facts"><div><dt>上次检查</dt><dd>${esc(u.checked?new Date(u.checked).toLocaleString():'尚未检查')}</dd></div><div><dt>下载线路</dt><dd>${esc(u.download_source||'自动选择')}</dd></div><div><dt>最低版本</dt><dd>${esc(s.policy?.minimum||'尚未读取')}</dd></div><div><dt>运行状态</dt><dd>${esc(s.policy?.blocked?s.policy.reason:(s.policy?.paused?'更新已暂停':'允许运行'))}</dd></div></dl>${u.notes?`<div class="release-notes"><h3>这一版更新了什么</h3><p>${esc(u.notes)}</p></div>`:''}${fu.stage==='approval_required'?`<div class="notice"><strong>新版需要确认权限变更</strong><pre class="preview">${esc(JSON.stringify(fu.changes,null,2))}</pre><button data-framework-approve>确认这些权限并更新</button></div>`:''}<div class="actions"><button data-update-check>${u.status==='checking'?'正在检查…':'检查更新'}</button><button data-share-install>给别人安装</button>${u.status==='ahead'?'':'<button class="primary" data-update-install>立即在线更新</button>'}<a class="release-link" href="https://github.com/Jay1023CN/Mengka-NT-plugins/releases" target="_blank" rel="noopener">历史版本</a></div></div>`)+`</div>`;
 }
 async function waitForUpdateCheck(){await post('/api/update/check');let latest;for(let i=0;i<240;i++){latest=await api('/api/service');S.service=latest;if(latest.update?.status!=='checking')break;if(i===0)render();if(i===40||i===120||i===200)toast('更新源还在响应，继续检查中…');await new Promise(resolve=>setTimeout(resolve,500));}if(latest?.update?.status==='checking')throw new Error('更新源响应较慢，检查仍在后台进行；稍后重新打开此页即可查看结果。');S.service=latest;render();return latest;}
 async function beginOnlineUpdate(){if(S.info?.preview){toast('这里是界面预览，实际更新请在已安装的插件后台操作');return;}const latest=await waitForUpdateCheck();if(latest.update?.status==='error')throw new Error(latest.update.error||'版本检查失败');if(latest.update?.status==='ahead')throw new Error('更新源版本低于当前安装版本');if(latest.update?.status==='current'){toast('当前已经是最新版');return;}if(latest.update?.status!=='available')throw new Error('版本检查没有完成，请稍后重试');if(S.service?.managed){let session=await api('/api/framework/session'),username='';while(!session.authenticated){const data=await api('/api/framework/captcha'),captcha=data.captcha;if(!captcha?.captchaId||!captcha.image)throw new Error('当前萌卡没有返回有效的图形验证码');const answer=await dialog('登录当前萌卡，完成在线更新',[{key:'username',label:'萌卡管理员账号',required:true,hint:'登录目标：'+data.origin+'。密码只用于本次登录，不保存。'},{key:'password',label:'萌卡管理员密码',type:'password',required:true},{key:'image',label:'图形验证码',type:'image'},{key:'code',label:'输入图中的验证码',required:true}],{username,password:'',image:captcha.image,code:''},'登录并更新');if(!answer)return;username=answer.username;try{await post('/api/framework/login',{username:answer.username,password:answer.password,captcha_id:captcha.captchaId,captcha_code:answer.code});answer.password='';session=await api('/api/framework/session');}catch(err){answer.password='';toast(err.message,true);}}}await post('/api/update/install');sessionStorage.setItem('catherina-update-from',S.info.version);toast('正在安装更新，完成后会自动重启');S.page='service';S.service=await api('/api/service');render();}
 function monitor(){return panel('监控记录',`<div class="panel-body monitor-body"><div class="actions"><button data-monitor-reload>重新读取</button><button data-monitor-clear>清空当前账号记录</button></div><div id="monitor-rows" class="monitor-records" data-state="loading" role="status" aria-live="polite"><p>正在读取…</p></div></div>`);}
 async function loadMonitor(){const node=$('#monitor-rows');if(!node)return;node.dataset.state='loading';node.innerHTML='<p>正在读取…</p>';try{const data=await api('/api/monitor');const items=data.items||[];node.dataset.state=items.length?'ready':'empty';if(!items.length){node.innerHTML='<p>还没有记录，请先在功能页开启监控并指定群。</p>';return;}const labels={account_online:'账号上线',account_offline:'账号离线',group_message_received:'群消息',private_message_received:'好友消息',group_message_recalled:'群消息撤回',friend_message_recalled:'好友消息撤回',user_poked:'收到戳一戳',group_request_received:'收到入群申请',friend_request_received:'收到好友申请'};node.innerHTML=items.map(r=>`<article class="monitor-entry"><header><time>${esc(new Date(r.created*1000).toLocaleString())}</time><span>${esc(labels[r.kind]||r.kind||'事件')}</span></header><div>${esc(r.body||'—')}</div></article>`).join('');}catch(err){node.dataset.state='error';node.innerHTML=`<p>${esc(err.message)}</p>`;}}
 function rememberDebug(){const mode=S.debugMode||'mengka',draft=S.debugDrafts[mode];for(const key of Object.keys(draft)){const node=$('#debug-'+key);if(node)draft[key]=node.value;}}
 function debug(){const mode=S.debugMode||'mengka',draft=S.debugDrafts[mode],result=S.debugResults[mode];
  const presets=[['get_bot_info','账号状态'],['get_group_list','群聊列表'],['get_friend_list','好友列表'],['get_group_member_list','群成员列表']];
  const controls=mode==='mengka'?`<p class="service-help">使用当前选中的 QQ；账号和协议自动填写。</p><div class="debug-presets">${presets.map(([action,label])=>`<button data-debug-preset="${action}" ${S.debugBusy?'disabled':''}>${label}</button>`).join('')}</div><label class="field"><span>接口名称</span><input id="debug-action" list="debug-actions" value="${esc(draft.action)}" autocomplete="off"><datalist id="debug-actions">${(S.info.actions||[]).map(x=>`<option value="${esc(x)}"></option>`).join('')}</datalist></label><label class="field"><span>请求参数（JSON 对象）</span><textarea id="debug-params" class="code-input" rows="5" spellcheck="false">${esc(draft.params)}</textarea><small>读取完整好友或群成员列表可能需要约 1 分钟，请等待当前请求完成。</small></label>`:`<div class="request-line"><label class="field"><span>方法</span><select id="debug-method">${['GET','POST','PUT','PATCH','DELETE','HEAD','OPTIONS'].map(x=>`<option ${draft.method===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field"><span>请求地址</span><input id="debug-url" type="url" value="${esc(draft.url)}" placeholder="https://example.com/api"></label></div><label class="field"><span>请求头（JSON 对象）</span><textarea id="debug-headers" class="code-input" rows="3" spellcheck="false">${esc(draft.headers)}</textarea></label><label class="field"><span>请求体</span><textarea id="debug-body" class="code-input" rows="6" spellcheck="false">${esc(draft.body)}</textarea></label>`;
  return `<div class="toolbar"><div class="tabs"><button data-debug-mode="mengka" class="${mode==='mengka'?'active':''}" ${S.debugBusy?'disabled':''}>萌卡接口</button><button data-debug-mode="http" class="${mode==='http'?'active':''}" ${S.debugBusy?'disabled':''}>HTTP 请求</button></div></div><div class="debug-layout">`+panel('请求',`<div class="panel-body"><fieldset class="debug-fields" ${S.debugBusy?'disabled':''}>${controls}</fieldset><div class="actions"><button class="primary" data-debug-send ${S.debugBusy?'disabled':''}>${S.debugBusy?'正在等待响应…':'发送请求'}</button></div></div>`)+`<section class="panel debug-results"><header class="panel-heading"><h2>响应结果</h2><button data-debug-copy ${result?.body?'':'disabled'}>复制结果</button></header><div class="panel-body"><p id="debug-meta" class="service-help ${result?.error?'inline-error':''}" role="status">${esc(result?.meta||'选择常用接口，或填写请求后发送。')}</p><pre id="debug-result" class="debug-output">${esc(result?.body||'返回内容会显示在这里。')}</pre></div></section></div>`;
 }
 async function sendDebug(){if(S.debugBusy)return;rememberDebug();const mode=S.debugMode||'mengka',draft=S.debugDrafts[mode];let body;
  try{if(mode==='mengka'){const params=JSON.parse(draft.params||'{}');if(!params||typeof params!=='object'||Array.isArray(params))throw new Error('请求参数必须是 JSON 对象');body={mode,action:draft.action.trim(),params};}else{const headers=JSON.parse(draft.headers||'{}');if(!headers||typeof headers!=='object'||Array.isArray(headers)||Object.values(headers).some(x=>typeof x!=='string'))throw new Error('请求头必须是键和值均为文本的 JSON 对象');body={mode,url:draft.url.trim(),method:draft.method,headers,body:draft.body};}
   S.debugBusy=true;S.debugResults[mode]={meta:'正在等待 '+(body.action||'HTTP')+' 响应…',body:''};render();
   const r=await post('/api/debug',body,{timeout:315000});let output;if(Object.hasOwn(r,'result'))output=JSON.stringify(r.result,null,2);else{let content=r.body;try{content=JSON.stringify(JSON.parse(content),null,2);}catch{}output=JSON.stringify(r.headers,null,2)+'\n\n'+content;}
   S.debugResults[mode]={meta:`${r.action?`${r.action} / ${r.account}`:`HTTP ${r.status}`} · ${r.milliseconds} ms${r.truncated?' · 内容较长，显示前 256 KiB':''}`,body:output};
  }catch(error){S.debugResults[mode]={meta:'请求未完成',body:error.message,error:true};}
  finally{S.debugBusy=false;if(S.page==='debug')render();}
 }
 async function editMenu(index){const c=S.global.config,old=index===null?{trigger:'',reply:'',global:true,permit:[]}:c.menus[index];await dialog(index===null?'添加菜单':'编辑菜单',[{key:'trigger',label:'触发词',required:true},{key:'reply',label:'实际回复内容',type:'textarea',rows:10,required:true,hint:'所有 QQ 共用；支持换行和【发送者QQ】等变量。'},{key:'global',label:'好友和群都可触发',type:'checkbox'},{key:'permit',label:'触发人员 QQ',hint:'留空允许所有人；填写后仅本人、额外管理 QQ 和名单内用户可触发。'}],{...old,permit:(old.permit||[]).join(',')},'保存菜单',async result=>{const menu={...result,permit:parseIDs(result.permit)},menus=clone(S.global.config.menus||[]);if(index===null)menus.push(menu);else{const current=menus.findIndex(item=>item.trigger===old.trigger);if(current<0)throw new Error('这条菜单已被删除，请关闭后重新选择。');menus[current]=menu;}await saveShared({menus});});}
 function parseIDs(value){return String(value).split(/[,，\s]+/).filter(Boolean).map(x=>{const id=Number(x);if(!Number.isSafeInteger(id)||id<=0)throw new Error('QQ 号码格式不正确');return id;});}
 async function editQA(index){const c=config(),items=Object.entries(c.qa),old=index===null?['','']:items[index];const result=await dialog(index===null?'添加问答':'编辑问答',[{key:'q',label:'问题',required:true},{key:'a',label:'回答',type:'textarea',required:true}],{q:old[0],a:old[1]},'保存问答',async value=>{const qa={...config().qa};if(index!==null)delete qa[old[0]];if(value.q!==old[0]&&Object.hasOwn(qa,value.q))throw new Error('这个问题已经存在，请编辑已有回答。');qa[value.q]=value.a;await save({qa},false);});if(result)render();}
 function durationParts(seconds){if(seconds>=3600&&seconds%3600===0)return {value:seconds/3600,unit:'hours'};if(seconds>=60&&seconds%60===0)return {value:seconds/60,unit:'minutes'};return {value:seconds,unit:'seconds'};}
