 async function saveDraft(){if((!S.dirty&&!S.globalDirty)||S.busy)return;if(S.globalDirty)await saveGlobal();if(!S.dirty)return;let patch=readFields();$$('[data-json]').forEach(n=>{try{patch[n.dataset.field]=JSON.parse(n.value||'{}');}catch{throw new Error('群级配置不是有效的 JSON');}});const sent=JSON.stringify(patch);const button=$('#save');button.disabled=true;try{await save(patch,false);let current=readFields();$$('[data-json]').forEach(n=>{current[n.dataset.field]=JSON.parse(n.value||'{}');});if(JSON.stringify(current)===sent)setDirty(false);else setDirty(true);}finally{button.disabled=false;}}
